      "@Component({ providers: [MyService] })  // component-level providers",
      "@Component({ host: { '[class.active]': 'isActive', '(click)': 'onClick()' } })  // host bindings + listeners",
      "@Component({ inputs: ['name'], outputs: ['change'] })  // legacy input/output declaration",
