      "{{ name | uppercase }}  // UpperCasePipe",
      "{{ name | lowercase }}  // LowerCasePipe",
      "{{ price | currency:'USD':'symbol':'1.2-2' }}  // CurrencyPipe",
      "{{ num | number:'3.1-2' }}  // DecimalPipe",
      "{{ pct | percent:'1.0-2' }}  // PercentPipe",
      "{{ observable$ | async }}  // AsyncPipe (auto-subscribe/unsubscribe)",
