      "form = new FormGroup({ name: new FormControl('', Validators.required), email: new FormControl('', [Validators.required, Validators.email]) })  // FormGroup with validators",
      "<form [formGroup]=\"form\" (ngSubmit)=\"submit()\">  // reactive form binding",
      "<input formControlName=\"name\" />  // bind FormControl to input",
      "<div formGroupName=\"address\">  // nested FormGroup",
      "<div formArrayName=\"items\">  // FormArray binding",
      "fb = inject(FormBuilder); this.form = this.fb.group({ name: ['', Validators.required], email: [''] })  // FormBuilder",
      "fb.array([fb.control('')])  // FormArray via FormBuilder",
      "this.form.get('name')?.value  // access control value",
      "this.form.patchValue({ name: 'John' })  // partial update",
      "this.form.setValue({ name: 'John', email: 'j@e.co' })  // full update (all fields required)",
      "this.form.reset()  // reset form to initial state",
      "form.controls.name.setValidators([Validators.required, Validators.email])  // set validators dynamically",
      "form.controls.name.updateValueAndValidity()  // recalculate validity",
      "Validators.required  // required field validator",
      "Validators.minLength(3)  // min length",
      "Validators.maxLength(100)  // max length",
      "Validators.pattern('[a-z]+')  // regex pattern",
