      "asyncValidator(control: AbstractControl): Promise<ValidationErrors | null> { return fetch('/check').then(r => r.ok ? null : { taken: true }) }  // async validator",
      "form.controls.name.valueChanges.subscribe(v => console.log(v))  // react to value changes",
      "form.controls.name.statusChanges.subscribe(s => console.log(s))  // VALID, INVALID, PENDING, DISABLED",
