      "{ path: 'admin', loadComponent: () => import('./admin.component').then(m => m.AdminComponent) }  // lazy load standalone component",
      "{ path: 'admin', loadChildren: () => import('./admin.module').then(m => m.AdminModule) }  // lazy load module",
      "canActivate: [() => inject(AuthService).isLoggedIn()]  // functional guard (Angular 15+)",
