    "Router": [
      "const router = express.Router()  // create isolated router",
      "router.get('/', handler)  // register route on router",
      "router.post('/', handler)  // POST route",
      "router.put('/:id', handler)  // PUT route",
      "router.patch('/:id', handler)  // PATCH route",
      "router.delete('/:id', handler)  // DELETE route",
      "router.all('/webhook', handler)  // match any HTTP method",
      "router.use(middleware)  // apply middleware to all routes in this router",
      "router.use('/admin', adminRoutes)  // mount sub-router",
      "router.param('id', (req, res, next, val) => { next() })  // param middleware",
      "router.route('/').get(getAll).post(create)  // chainable route",
      "const router = express.Router({ mergeParams: true })  // merge params from parent route",
      "const router = express.Router({ caseSensitive: true })  // case-sensitive matching",
      "const router = express.Router({ strict: true })  // strict trailing slash",
      "app.use('/api', router)  // mount router on app",
    ],
    "Middleware": [
      "express.json()  // built-in JSON body parser",
      "express.urlencoded({ extended: true })  // URL-encoded body parser",
      "express.static('public')  // serve static files from directory",
      "express.Router()  // create modular router",
      "express.query()  // auto-parse query strings (built-in)",
      "const cors = require('cors'); app.use(cors({ origin: 'https://example.com' }))  // CORS middleware",
      "const morgan = require('morgan'); app.use(morgan('combined'))  // HTTP request logger",
      "const helmet = require('helmet'); app.use(helmet())  // security headers",
      "const compression = require('compression'); app.use(compression())  // gzip/brotli compression",
      "const session = require('express-session'); app.use(session({ secret: 'key', resave: false, saveUninitialized: true, cookie: { secure: true } }))  // session middleware",
      "const cookieParser = require('cookie-parser'); app.use(cookieParser())  // cookie parsing",
      "app.use((req, res, next) => { console.log(req.method, req.url); next() })  // custom middleware",
      "app.use('/api', (req, res, next) => { if (!req.headers.authorization) return res.status(401).end(); next() })  // path-scoped middleware",
      "const passport = require('passport'); app.use(passport.initialize()); app.use(passport.session())  // authentication middleware",
      "const multer = require('multer'); const upload = multer({ dest: 'uploads/' }); app.post('/upload', upload.single('file'), handler)  // file upload middleware",
      "const rateLimit = require('express-rate-limit'); const limiter = rateLimit({ windowMs: 15*60*1000, max: 100 }); app.use(limiter)  // rate limiting",
      "const timeout = require('connect-timeout'); app.use(timeout('5s'))  // request timeout",
      "const responseTime = require('response-time'); app.use(responseTime())  // X-Response-Time header",
    ],
    "Error Handling": [
      "app.use((err, req, res, next) => { console.error(err.stack); res.status(500).send('Something broke!') })  // global error handler (4 params)",
      "app.use((err, req, res, next) => { if (err instanceof ValidationError) { return res.status(400).json({ error: err.message }) }; next(err) })  // typed error handling",
      "class HttpError extends Error { constructor(status, message) { super(message); this.status = status } }; throw new HttpError(404, 'Not found')  // custom HTTP error class",
      "app.use((req, res, next) => { res.status(404).json({ error: 'Not found' }) })  // 404 handler (must be after routes)",
      "next(err)  // pass error to error handler",
      "// npm install express-async-errors; then async route errors auto-forward  // async error handling",
      "app.use((err, req, res, next) => { res.status(err.status || 500).json({ message: err.message, stack: process.env.NODE_ENV === 'development' ? err.stack : undefined }) })  // JSON error response with stack in dev",
      "process.on('uncaughtException', err => { console.error('Uncaught:', err); process.exit(1) })  // catch uncaught exceptions",
      "process.on('unhandledRejection', (reason, promise) => { console.error('Unhandled Rejection:', reason) })  // catch unhandled rejections",
    ],
