      "for v := range ch {\n}  // range over channel (reads until closed)",
      "switch x {\ncase 1:\n    fmt.Println(\"one\")\ncase 2:\n    fallthrough\ncase 3:\n    fmt.Println(\"two or three\")\ndefault:\n    fmt.Println(\"other\")\n}  // switch (no need break; fallthrough goes to next)",
      "switch {\ncase x > 0:\n    fmt.Println(\"positive\")\ncase x < 0:\n    fmt.Println(\"negative\")\n}  // switch true (replaces if-else chain)",
      "switch x := val.(type) {\ncase int:\n    fmt.Println(x + 1)\ncase string:\n    fmt.Println(len(x))\n}  // type switch",
      "select {\ncase msg := <-ch1:\n    fmt.Println(msg)\ncase ch2 <- val:\n    fmt.Println(\"sent\")\ndefault:\n    fmt.Println(\"neither ready\")\n}  // select waits on channel operations",
      "defer f.Close()  // defers execution until surrounding function returns",
      "defer func() {\n    if r := recover(); r != nil {\n        fmt.Println(\"recovered:\", r)\n    }\n}()  // defer with recover to catch panic",
