      "ch := make(chan int, 10)  // creates buffered channel",
      "ch <- 42  // sends value to channel",
      "val := <-ch  // receives from channel",
      "val, ok := <-ch  // receive; ok=false if channel closed",
      "close(ch)  // closes channel",
      "for v := range ch {\n}  // reads until channel is closed",
      "select {\ncase v := <-ch1:\n    fmt.Println(v)\ndefault:\n    fmt.Println(\"no ready\")\n}  // non-blocking select with default",
      "var mu sync.Mutex\nmu.Lock()\n// critical section\nmu.Unlock()  // mutex mutual exclusion",
      "var mu sync.RWMutex\nmu.RLock()\n// read section\nmu.RUnlock()  // read-lock (multiple concurrent readers)",
      "var wg sync.WaitGroup\nwg.Add(1)\ngo func() { defer wg.Done(); work() }()\nwg.Wait()  // waits for goroutines to complete",
      "var once sync.Once\nonce.Do(func() { fmt.Println(\"once\")\n})  // runs function exactly once",
      "var sm sync.Map\nsm.Store(\"k\", \"v\")\nsm.Load(\"k\")  // concurrent-safe map",
      "var counter atomic.Int64\ncounter.Add(1)\ncounter.Load()  // atomic operations (Go 1.19+)",
      "var v atomic.Value\nv.Store(x)\nx = v.Load().(T)  // atomic store/load for any type",
      "ctx, cancel := context.WithCancel(parent)\nctx, cancel := context.WithTimeout(parent, 5*time.Second)\nctx := context.WithValue(parent, key, val)  // context patterns",
      "ctx.Done()  // channel closed when context is cancelled/timeout",
      "ctx.Err()  // nil if not done, Canceled or DeadlineExceeded",
      "select {\ncase <-ctx.Done():\n    return ctx.Err()\ncase result <- work():\n}  // context-aware select",
      "runtime.GOMAXPROCS(4)  // sets max OS threads for goroutines",
