  "graphql": {
    "Schema": [
      "type Query { hello: String }  // Define Query type with field",
      "type Mutation { createUser(name: String!): User }  // Define Mutation type",
      "type User { id: ID! name: String! email: String }  // Non-null fields with !",
      "[Post!]!  // Non-null list of non-null Posts",
      "input CreateUserInput { name: String! email: String! }  // Input type for mutations",
      "enum Role { ADMIN USER GUEST }  // Enum type definition",
      "type Query { users(limit: Int): [User] }  // Query with optional argument",
    ],
    "Queries": [
      "query { user(id: \"1\") { name email } }  // Basic query with argument",
      "query getUser($id: ID!) { user(id: $id) { name } }  // Query with variable",
      "fragment userFields on User { name email avatar }  // Reusable fragment",
      "query { author: user(id: \"1\") { name } reviewer: user(id: \"2\") { name } }  // Aliases",
      "query { users { ...userFields } }  // Spread fragment in query",
      "query ($limit: Int) { users(limit: $limit) { id name } }  // Variable query",
      "{ posts { title author { name } } }  // Nested relation query",
    ],
    "Mutations": [
      "mutation { createUser(name: \"Alice\") { id name } }  // Create user mutation",
      "mutation ($input: CreateUserInput!) { createUser(input: $input) { id } }  // Mutation with input type",
      "mutation { updateUser(id: \"1\", name: \"Bob\") { id name } }  // Update returning data",
      "mutation { deleteUser(id: \"1\") { id } }  // Delete and return deleted ID",
      "mutation ($input: [CreateUserInput!]!) { batchCreate(input: $input) { id } }  // Batch mutation",
      "mutation { login(email: \"a@b.com\", password: \"secret\") { token user { id } } }  // Auth mutation",
      "mutation { addPost(title: \"Hi\", content: \"...\") { ...postFields } }  // Mutation with fragment",
    ],
    "Resolvers": [
      "Query: { user: (_, { id }, context) => context.db.users.findUnique({ where: { id } }) }  // Field resolver",
      "User: { posts: (parent, _, context) => context.db.posts.findMany({ where: { authorId: parent.id } }) }  // Relation resolver",
      "Mutation: { createUser: (_, { input }, context) => context.db.users.create({ data: input }) }  // Mutation resolver",
      "Query: { users: (_, args, context) => context.db.users.findMany() }  // List resolver with context",
      "User: { fullName: (parent) => `${parent.firstName} ${parent.lastName}` }  // Computed field",
      "const batchUsers = new DataLoader(ids => db.users.findMany({ where: { id: { in: ids } } }))  // DataLoader batching",
      "{ posts: (parent, _, { loaders }) => loaders.postsByAuthor.load(parent.id) }  // DataLoader in resolver",
    ],
  },
