      "SELECT REVERSE('hello');  // reverse string: 'olleh'",
      "SELECT REPEAT('ha', 3);  // repeat string N times: 'hahaha'",
      "SELECT LPAD('5', 3, '0');  // left pad to length with string: '005'",
