      "export async function generateMetadata({ params }) { const post = await getPost(params.id); return { title: post.title, description: post.excerpt } }  // dynamic metadata generation",
      "export const metadata = { title: { default: 'My Site', template: '%s | My Site' }, description: '...', keywords: ['next', 'react'] }  // metadata with title template",
      "export const metadata = { openGraph: { title: '...', description: '...', images: [{ url: '/og.png', width: 1200, height: 630 }] } }  // Open Graph meta tags",
      "export const metadata = { twitter: { card: 'summary_large_image', title: '...', description: '...', images: ['/twitter.png'] } }  // Twitter card meta",
      "export const metadata = { robots: { index: true, follow: true, nocache: true } }  // robots meta",
