      "<Link href=\"/post/[id]\" as={`/post/${id}`}>Post</Link>  // dynamic route link (pages router)",
      "<Link href=\"/dashboard\" prefetch={false}>  // disable prefetch",
      "<Link href=\"/dashboard\" replace>  // replace current history entry",
      "<Link href=\"/dashboard\" scroll={false}>  // disable scroll to top",
      "import { useRouter } from 'next/navigation'; const router = useRouter(); router.push('/dashboard')  // programmatic navigation (app router)",
