      "router.back()  // go back",
      "router.refresh()  // refresh current route (re-render server components)",
      "router.prefetch('/dashboard')  // prefetch route manually",
      "import { usePathname } from 'next/navigation'  // get current pathname (app router)",
      "import { useSearchParams } from 'next/navigation'  // get search params (app router, client)",
      "import { useParams } from 'next/navigation'  // get dynamic route params",
      "import { redirect } from 'next/navigation'; redirect('/login')  // redirect in server component/action",
      "import { permanentRedirect } from 'next/navigation'; permanentRedirect('/new-url')  // 308 redirect",
      "import { notFound } from 'next/navigation'; notFound()  // trigger not-found page",
      "// middleware.ts: export function middleware(request) { return NextResponse.redirect(new URL('/login', request.url)) }  // middleware redirect",
      "// middleware.ts: export { default } from 'next-auth/middleware'; export const config = { matcher: ['/dashboard/:path*'] }  // auth middleware with matcher",
