      "SELECT phraseto_tsquery('english', 'quick brown');  // phrase text to tsquery (terms must appear consecutively)",
      "SELECT websearch_to_tsquery('english', 'quick brown -fox');  // web-style search: +required -excluded",
      "SELECT to_tsvector('english', body) @@ to_tsquery('english', 'quick & fox') FROM articles;  // match: tsvector @@ tsquery",
      "SELECT ts_rank(to_tsvector('english', body), to_tsquery('english', 'quick')) FROM articles;  // rank relevance of match",
      "SELECT ts_headline('english', body, to_tsquery('english', 'quick'), 'MaxWords=20, MinWords=5');  // generate highlighted snippet",
