      "CREATE FUNCTION create_user(p_name TEXT, OUT new_id INT) AS $$ BEGIN INSERT INTO users (name) VALUES (p_name) RETURNING id INTO new_id; END; $$ LANGUAGE plpgsql;  // function with OUT parameter",
      "CREATE FUNCTION swap(INOUT a INT, INOUT b INT) AS $$ DECLARE t INT := a; BEGIN a := b; b := t; END; $$ LANGUAGE plpgsql;  // function with INOUT parameters",
      "CREATE FUNCTION sum_variadic(VARIADIC args INT[]) RETURNS INT AS $$ BEGIN RETURN (SELECT SUM(v) FROM unnest(args) AS v); END; $$ LANGUAGE plpgsql;  // variadic function (variable arg count)",
      "CREATE FUNCTION raise_example() RETURNS VOID AS $$ BEGIN RAISE INFO 'hello %', now(); END; $$ LANGUAGE plpgsql;  // RAISE: INFO, WARNING, EXCEPTION",
      "CREATE FUNCTION dynamic_sql() RETURNS INT AS $$ DECLARE r INT; BEGIN EXECUTE 'SELECT 1 + 1' INTO r; RETURN r; END; $$ LANGUAGE plpgsql;  // dynamic SQL with EXECUTE",
      "CREATE FUNCTION loop_example() RETURNS INT AS $$ DECLARE i INT := 0; BEGIN FOR i IN 1..10 LOOP CONTINUE WHEN i = 5; END LOOP; RETURN i; END; $$ LANGUAGE plpgsql;  // FOR loop with CONTINUE",
      "CREATE FUNCTION while_example() RETURNS INT AS $$ DECLARE i INT := 0; BEGIN WHILE i < 10 LOOP i := i + 1; END LOOP; RETURN i; END; $$ LANGUAGE plpgsql;  // WHILE loop",
      "CREATE FUNCTION exception_example() RETURNS TEXT AS $$ BEGIN INSERT INTO users VALUES (1, 'test'); RETURN 'ok'; EXCEPTION WHEN unique_violation THEN RETURN 'duplicate'; WHEN OTHERS THEN RETURN 'error'; END; $$ LANGUAGE plpgsql;  // EXCEPTION handling",
