      "page.getByTestId('login-form')  // locate by data-testid attribute",
      "page.getByLabel('Email')  // locate by associated label",
      "page.getByPlaceholder('Enter name')  // locate by placeholder",
      "page.getByAltText('logo')  // locate image by alt text",
