      "await page.getByLabel('Name').fill('Alice')  // fill input field",
      "await page.getByRole('combobox').selectOption('option')  // select dropdown",
      "await page.getByRole('checkbox').check()  // check checkbox",
      "await page.getByLabel('Terms').uncheck()  // uncheck checkbox",
