  "prisma": {
    "Schema": [
      "model User { id Int @id @default(autoincrement()) }  // Model with auto-increment ID",
      "email String @unique  // Unique constraint on email",
      "@default(now())  // Default value as current timestamp",
      "model Post { author User @relation(fields: [authorId], references: [id]) authorId Int }  // Relation field",
      "model Profile { user User @relation(fields: [userId], references: [id]) userId Int @unique }  // One-to-one relation",
      "@@unique([firstName, lastName])  // Compound unique constraint",
      "model Tag { id Int @id @default(autoincrement()) name String @unique posts Post[] }  // Many-to-many via implicit",
    ],
    "CRUD": [
      "prisma.user.create({ data: { name: 'Alice', email: 'alice@example.com' } })  // Create record",
      "prisma.user.findMany({ where: { role: 'ADMIN' } })  // Find multiple with filter",
      "prisma.user.findUnique({ where: { email: 'alice@example.com' } })  // Find by unique field",
      "prisma.user.update({ where: { id: 1 }, data: { name: 'Bob' } })  // Update record",
      "prisma.user.delete({ where: { id: 1 } })  // Delete record",
      "prisma.user.upsert({ where: { email: 'a@b.com' }, update: { name: 'A' }, create: { name: 'A', email: 'a@b.com' } })  // Upsert",
      "prisma.user.count({ where: { active: true } })  // Count matching records",
    ],
    "Relations": [
      "prisma.user.findMany({ include: { posts: true } })  // One-to-many: user with posts",
      "prisma.user.create({ data: { name: 'A', posts: { create: { title: 'Post' } } } })  // Nested create",
      "prisma.post.update({ where: { id: 1 }, data: { author: { connect: { id: 2 } } } })  // Connect existing",
      "prisma.post.create({ data: { title: 'P', tags: { connect: [{ id: 1 }, { id: 2 }] } } })  // Many-to-many connect",
      "prisma.user.update({ where: { id: 1 }, data: { posts: { deleteMany: { title: { contains: 'Spam' } } } } })  // Delete nested",
      "prisma.user.create({ data: { name: 'B', profile: { create: { bio: 'Hi' } } } })  // One-to-one nested create",
      "prisma.user.findMany({ include: { posts: { include: { tags: true } } } })  // Deeply nested include",
    ],
    "Querying": [
      "prisma.user.findMany({ where: { email: { contains: 'example.com' } } })  // Filter with contains",
      "prisma.user.findUnique({ where: { id: 1 }, include: { posts: true } })  // Include relations",
      "prisma.user.findMany({ select: { id: true, name: true } })  // Select specific fields only",
      "prisma.user.findMany({ orderBy: { createdAt: 'desc' } })  // Order by field descending",
      "prisma.user.findMany({ skip: 10, take: 5 })  // Pagination: skip 10, take 5",
      "prisma.user.findMany({ where: { OR: [{ role: 'ADMIN' }, { role: 'MOD' }] } })  // OR filtering",
      "prisma.user.findMany({ cursor: { id: 10 }, take: 5, skip: 1 })  // Cursor-based pagination",
    ],
  },
