      "CREATE TABLE orders (id INTEGER PRIMARY KEY, uid INTEGER, FOREIGN KEY (uid) REFERENCES users(id) ON DELETE SET NULL);  // set FK to NULL when parent removed",
      "CREATE TABLE orders (id INTEGER PRIMARY KEY, uid INTEGER, FOREIGN KEY (uid) REFERENCES users(id) ON UPDATE CASCADE);  // cascade updates to FK when parent PK changes",
